/* JOURNEY 마스코트. 승인된 자체 제작 그림을 내장한 픽셀 스프라이트.
   공개 계약: window.JourneyArt={OUT,person}; cx=중심, fy=발바닥.
   화면 크기는 그대로 두고 캔버스 내부 해상도만 3배로 높여 작은 도트를 살린다.
   데이터 순서: 기본복 4개 / 주인공 동작 9개 / 친구 5명×3개 / 오른쪽 걷기 4복장×4프레임.
   외부 이미지·라이브러리·네트워크 요청 없이 동작한다. */
(function(){
'use strict';
const DATA=["","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","",""];
const SCALE=3,FRAME=84,INK='#302638';
const OUT={
 mil:{shirt:'#66694f',pants:'#545943',shoe:'#34313a',hat:'mil',cam:1},
 job:{shirt:'#fff3de',pants:'#37333e',shoe:'#34313a',hat:'job',apron:1},
 dw:{shirt:'#806087',pants:'#403844',shoe:'#f5effa',bag:1,hood:1},
 grad:{shirt:'#393441',pants:'#393441',shoe:'#34313a',hat:'grad',gown:1}
};
const FR_HAIR=['#6b4a2e','#1d2033','#e8c15a','#c44d7a','#3a6b8a'];
const contexts=new WeakMap(),waiting=new Map(),variants=new Map(),mouths=new Map();
let ready=false;
const images=DATA.map(src=>{const im=new Image();im.src='data:image/png;base64,'+src;return im});
const loaded=Promise.all(images.map(im=>im.decode().catch(()=>new Promise(resolve=>{if(im.complete)resolve();else{im.onload=resolve;im.onerror=resolve}}))));

function prepare(c){
 if(contexts.has(c))return;
 const canvas=c.canvas,w=canvas.width,h=canvas.height,alpha=c.globalAlpha;
 const old=document.createElement('canvas');old.width=w;old.height=h;old.getContext('2d').drawImage(canvas,0,0);
 canvas.width=w*SCALE;canvas.height=h*SCALE;
 c.setTransform(SCALE,0,0,SCALE,0,0);c.imageSmoothingEnabled=false;c.globalAlpha=alpha;c.drawImage(old,0,0,w,h);
 contexts.set(c,{w,h});
}
// engine.js가 save()를 쓰기 전에 실제 장면의 캔버스부터 준비한다.
const main=document.getElementById('jy-cv');if(main)prepare(main.getContext('2d'));

loaded.then(()=>{
 ready=true;
 waiting.forEach((p,c)=>{if(c.canvas.id==='jy-cv')return;const size=contexts.get(c);c.clearRect(0,0,size.w,size.h);person(c,p.cx,p.fy,p.o)});waiting.clear();
 if(main&&matchMedia('(prefers-reduced-motion: reduce)').matches&&window.__jy)window.__jy.render(window.__jy.total-1);
 window.dispatchEvent(new Event('journeyartready'));
});

function friendIndex(o){
 const exact=FR_HAIR.indexOf(o.hair);if(exact>=0)return exact;
 return o.long?1:0;
}
function pick(O,o){
 const a=o.arm||'down';
 if(o.glasses&&(o.legs==='A'||o.legs==='B')){
  const row=O.hat==='mil'?0:O.hat==='job'?1:O.hat==='grad'?3:2;
  const phase=Number.isFinite(o.walkFrame)?Math.floor(o.walkFrame)%4:o.legs==='A'?0:2;
  return 28+row*4+phase;
 }
 if(!o.glasses){const col=a==='up'?2:(a==='raise'||a==='salute'?1:0);return 13+friendIndex(o)*3+col}
 if(O.hat==='mil')return a==='salute'?4:0;
 if(O.hat==='job')return a==='scan'?5:a==='scan2'?6:1;
 if(O.hat==='grad')return a==='diploma'?12:3;
 if(o.legs==='sit'||a==='tr1'||a==='tr2')return a==='tr2'?8:7;
 if(a==='type1'||a==='type2')return 9;
 if(a==='up')return 10;
 if(a==='raise')return 11;
 return 2;
}

function rgb(hex){const v=parseInt(hex.replace('#',''),16);return[v>>16&255,v>>8&255,v&255]}
function recolor(index,o,O){
 const isFriend=index>=13&&index<28,shirt=o.shirt||(isFriend&&O.shirt),skin=o.skin,hair=o.hair;
 const noBag=index===2&&o.nobag;
 if(!shirt&&!skin&&!noBag&&!(hair&&index<13))return images[index];
 const key=[index,shirt,skin,noBag,hair].join('|');if(variants.has(key))return variants.get(key);
 const cv=document.createElement('canvas');cv.width=cv.height=FRAME;const c=cv.getContext('2d');c.drawImage(images[index],0,0);
 const data=c.getImageData(0,0,FRAME,FRAME),p=data.data,original=new Uint8ClampedArray(p);
 const tint=(i,target)=>{const lum=(p[i]+p[i+1]+p[i+2])/3,tl=(target[0]+target[1]+target[2])/3,f=Math.max(.38,Math.min(1.35,lum/Math.max(1,tl)));for(let j=0;j<3;j++)p[i+j]=Math.min(255,Math.round(target[j]*f))};
 const targetShirt=shirt?rgb(shirt):null,targetSkin=skin?rgb(skin):null,targetHair=hair?rgb(hair):null;
 for(let y=0;y<FRAME;y++)for(let x=0;x<FRAME;x++){
  const i=(y*FRAME+x)*4;if(!p[i+3])continue;const r=p[i],g=p[i+1],b=p[i+2];
  if(noBag&&y>49&&r>145&&g>65&&b<140&&r>g*1.1){
   if(x<30||x>53){p[i+3]=0;continue}const j=(y*FRAME+44)*4;p[i]=original[j];p[i+1]=original[j+1];p[i+2]=original[j+2];continue;
  }
  if(targetSkin&&r>170&&g>105&&b>95&&r>g*1.06&&g-b>12&&g-b<60&&r-g<95&&y>28&&y<69){tint(i,targetSkin);continue}
  if(targetHair&&index<13&&y<48&&r<145&&g<135&&b>g*.92&&r>g*.88&&Math.max(r,g,b)>45){tint(i,targetHair);continue}
  if(targetShirt&&y>48&&y<69&&Math.max(r,g,b)>70&&Math.max(r,g,b)-Math.min(r,g,b)>22){
   const row=isFriend?Math.floor((index-13)/3):-1;
   const cloth=row===0?g>r*1.12:row===1?r>g*1.17&&b<r*.95:row===2?g>r*1.05&&g>b:row===3?r>g*.95&&g>b*1.25:b>g*1.12&&r>g*.9;
   if(cloth)tint(i,targetShirt);
  }
 }
 c.putImageData(data,0,0);variants.set(key,cv);return cv;
}

function drawBag(c){
 c.fillStyle=INK;c.fillRect(53,51,10,18);c.fillStyle='#ee9b49';c.fillRect(54,52,8,15);
 c.fillStyle='#b96339';c.fillRect(59,54,3,12);c.fillStyle='#ffbd66';c.fillRect(55,54,3,10);
}
function talk(c,index,dy=0){
 if(!mouths.has(index)){
  const cv=document.createElement('canvas');cv.width=cv.height=84;const cc=cv.getContext('2d');cc.drawImage(images[index],0,0);const p=cc.getImageData(0,0,84,84).data,points=[];
  for(let y=43;y<59;y++)for(let x=34;x<50;x++){const i=(y*84+x)*4,r=p[i],g=p[i+1],b=p[i+2];if(p[i+3]&&r>110&&g<130&&b<145&&r>g*1.3&&r>b*1.18)points.push({x,y})}
  if(points.length){const y=Math.max(...points.map(p=>p.y)),row=points.filter(p=>p.y>=y-1);mouths.set(index,{x:Math.round(row.reduce((a,p)=>a+p.x,0)/row.length),y:y-1})}else mouths.set(index,null);
 }
 const m=mouths.get(index);if(!m)return;c.fillStyle='#653447';c.fillRect(m.x,m.y+dy,2,2);c.fillStyle='#ee99a6';c.fillRect(m.x,m.y+dy+1,2,1);
}
/* 발과 손을 나누어 움직여 걷기와 타자 치기에 미세한 동작을 준다. */
function person(c,cx,fy,o={}){
 prepare(c);if(!ready){waiting.set(c,{cx,fy,o:{...o}});return}
 const O=o.outfit||OUT.dw,index=pick(O,o),img=recolor(index,o,O),friend=index>=13&&index<28;
 const arm=o.arm||'down',legs=o.legs||'stand',walk=legs==='A'||legs==='B';
 const mirror=index>=28?o.facing===-1:index===5||index===6||index===12;
 c.save();c.imageSmoothingEnabled=false;
 c.translate(Math.round(cx*SCALE)/SCALE,Math.round(fy*SCALE)/SCALE);
 c.scale(1/SCALE,1/SCALE);
 if(friend)c.scale(.9,.9);
 // 앉으면 발을 살짝 띄워 손 높이를 키보드에 맞춘다.
 if(legs==='sit'){
  c.fillStyle='#61546e';c.fillRect(-17,-21,3,21);c.fillRect(-16,-12,24,3);c.fillRect(5,-10,3,10);c.translate(0,-6);
 }
 c.translate(-42,-84);
 if(O.bag&&!o.nobag&&index>=9&&index<=11)drawBag(c);
 if(mirror){c.translate(84,0);c.scale(-1,1)}
 if(walk&&index>=28){
  // 머리는 고정하고 몸 아래는 실제 걷기 그림 네 장으로 바꾼다.
  // 발바닥은 같은 바닥에 맞추며 진행 방향과 얼굴 방향을 일치시킨다.
  const phase=(index-28)%4,head=images[index-phase],cut=52,bob=phase%2?-1:0;
  c.drawImage(img,0,cut,84,84-cut,0,cut,84,84-cut);
  c.drawImage(head,0,0,84,cut+1,0,bob,84,cut+1);
 }else if(walk){c.drawImage(img,0,0);
 }else if(index===6||index===8){
  // 스캔과 타자의 교대 프레임은 얼굴을 고정해 머리가 덜컥 움직이지 않게 한다.
  const fixed=index===6?5:7,cut=index===6?49:52;
  c.drawImage(img,0,cut,84,84-cut,0,cut,84,84-cut);
  c.drawImage(recolor(fixed,o,O),0,0,84,cut,0,0,84,cut);
 }else if(arm==='type2'){
  c.drawImage(img,0,0,84,52,0,0,84,52);c.drawImage(img,0,52,84,17,0,53,84,17);c.drawImage(img,0,69,84,15,0,69,84,15);
 }else if(legs==='jump'&&index!==10&&index!==12){
  c.drawImage(img,0,0,84,69,0,0,84,69);c.drawImage(img,0,69,84,15,0,66,84,15);
 }else c.drawImage(img,0,0);
 if(o.talk)talk(c,index===6?5:index===8?7:index);
 c.restore();
}
window.JourneyArt={OUT,person};
})();
